import React, { Component } from 'react'
//import Table from 'react-bootstrap/Table'
import Button from 'react-bootstrap/Button'
import Form from 'react-bootstrap/Form'
import Spinner from 'react-bootstrap/Spinner'
import DataTable from 'react-data-table-component'

class MessageForm extends Component {


    handleChange = changeEvent => {
      
          this.props.handleMessageChange(changeEvent.selectedRows);
    }
    
    handleSubmit = () => {
        this.props.handleMessageSubmit(this.state)
        //this.setState(this.initialState)
    }
    
    
    render() {
          
        const showMessageSubmitButton = false;
        const showMessageSubmitLoadingButton = false;
        
        return (
          
          <Form className="messageForm">

        <Form.Control
          type="text"
          name="searchUrl"
          onChange={this.handleChange} />
          
            <Button
                type="submit"
                value="Submit"
                onClick={e => {e.preventDefault(); this.handleSubmit()}}
                style={showMessageSubmitButton}>
                Submit
            </Button>
            
              <Button variant="primary" disabled style={showMessageSubmitLoadingButton}>
                <Spinner
                  as="span"
                  animation="grow"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                />
                Loading...
              </Button>
          </Form>
        )
    }

}

export default MessageForm
